/** The directory of a case, which has a configuration file of its own. */
export const directoryOf = (index: number) => `${index}-${cases[index].rule.replace(/^.*\//, "")}`;

export const filesOf = ({ rule, file, text, typed, options, also = [], compilerOptions }: Case): Record<string, string> => ({
  ".oxlintrc.json": JSON.stringify({
    plugins: ["typescript"],
    categories: { correctness: "off" },
    rules: { [rule]: options ? ["error", options] : "error", ...Object.fromEntries(also.map(it => [it, "error"])) },
  }),
  [file]: text,
  ...(typed && {
    "tsconfig.json": JSON.stringify({
      compilerOptions: { strict: true, target: "esnext", module: "esnext", lib: ["esnext", "dom"], ...compilerOptions },
    }),
  }),
});
